//! Automatically discover Luau scenarios and run as ordinary Cargo tests.
//!
//! Add this crate as a build-dependency. In `build.rs`:
//!
//! ```no_run
//! # // Keep the build.rs entry point visible without triggering needless_doctest_main.
//! fn main() {
//!     inslag_e2e_build::discover();
//! }
//! ```
//!
//! In `tests/e2e.rs`, define `fn run(path: &str)` to run an `inslag_e2e::Suite`,
//! then include the tests generated by your build script:
//!
//! ```ignore
//! include!(concat!(env!("OUT_DIR"), "/e2e_cases.rs"));
//! ```
//!
//! Put scenarios in `e2e/cases/**/*.test.luau` and run `cargo test --test e2e`.
//! Files ending in `.ignored.test.luau` require `-- --ignored`. Helper modules
//! can use ordinary `.luau` names without becoming tests.
use std::{collections::HashSet, env, fs, path::Path};

/// Generate one test per `e2e/cases/**/*.test.luau`, sorted by path.
///
/// Each test calls your `run` function with a path relative to `e2e/cases`.
/// Cargo reruns discovery when `e2e` changes, including new or removed files.
/// Panics if discovery fails, the suite is empty, or paths produce colliding
/// test names after punctuation is replaced with underscores.
pub fn discover() {
    println!("cargo:rerun-if-changed=e2e");
    let manifest = env::var_os("CARGO_MANIFEST_DIR").expect("Cargo manifest directory");
    let root = Path::new(&manifest).join("e2e/cases");
    let output = render(&root);
    fs::write(
        Path::new(&env::var_os("OUT_DIR").unwrap()).join("e2e_cases.rs"),
        output,
    )
    .expect("write discovered scenarios");
}

fn render(root: &Path) -> String {
    let mut files = Vec::new();
    collect(root, &mut files).expect("discover E2E scenarios");
    files.sort();
    assert!(!files.is_empty(), "the E2E suite must contain scenarios");
    let mut names = HashSet::new();
    let mut output = String::new();
    for path in files {
        let relative = path
            .strip_prefix(root)
            .unwrap()
            .to_str()
            .unwrap()
            .replace('\\', "/");
        let name: String = relative
            .chars()
            .map(|c| if c.is_ascii_alphanumeric() { c } else { '_' })
            .collect();
        assert!(
            names.insert(name.clone()),
            "colliding E2E test name: {name}"
        );
        if relative.ends_with(".ignored.test.luau") {
            output.push_str("#[ignore = \"explicit opt-in\"]\n");
        }
        output.push_str(&format!(
            "#[test]\nfn luau_{name}() {{ run({relative:?}); }}\n"
        ));
    }
    output
}

fn collect(root: &Path, files: &mut Vec<std::path::PathBuf>) -> std::io::Result<()> {
    for entry in fs::read_dir(root)? {
        let entry = entry?;
        // Do not follow directory symlinks out of the scenario root.
        if entry.file_type()?.is_dir() {
            collect(&entry.path(), files)?;
        } else if entry.file_type()?.is_file()
            && entry.path().to_string_lossy().ends_with(".test.luau")
        {
            files.push(entry.path());
        }
    }
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn discovery_tracks_additions_removals_ignored_cases_and_collisions() {
        let directory = tempfile::tempdir().unwrap();
        let root = directory.path();
        fs::create_dir(root.join("nested")).unwrap();
        fs::write(root.join("z.test.luau"), "").unwrap();
        fs::write(root.join("nested/a.ignored.test.luau"), "").unwrap();
        fs::write(root.join("helper.luau"), "").unwrap();
        let first = render(root);
        assert!(
            first.find("nested/a.ignored.test.luau").unwrap() < first.find("z.test.luau").unwrap()
        );
        assert!(first.contains("#[ignore = \"explicit opt-in\"]"));
        assert!(!first.contains("helper"));
        fs::remove_file(root.join("z.test.luau")).unwrap();
        assert!(!render(root).contains("z.test.luau"));
        fs::write(root.join("a-b.test.luau"), "").unwrap();
        fs::write(root.join("a_b.test.luau"), "").unwrap();
        assert!(std::panic::catch_unwind(|| render(root)).is_err());
    }
}
